def minOperations(n, k):
    # Initialize the minimum operations to 0
    min_operations = 0

    # Iterate over all possible indices
    for i in range(1, n+1):
        # If the current index is divisible by k, we can skip it
        if i % k == 0:
            continue

        # If the current index is not divisible by k, we need to add 1 to it
        else:
            min_operations += 1

    return min_operations

