def longestSemiRepetitiveSubstring(s):
    n = len(s)
    dp = [[0]*n for _ in range(n)]
    max_len = 0
    start = 0
    for i in range(n):
        for j in range(i+1, n):
            if s[i] == s[j]:
                dp[i][j] = 1
            else:
