    dp = [float('inf')] * (n + 1)
    dp[0] = 0
    for i in range(1, n + 1):
        for j in range(i):
            if time[j] <= i:
                dp[i] = min(dp[i], dp[j] + cost[j])
    return dp[n]

def minimumCost(nums, x):
    n = len(nums)
