    for i in range(1, n + 1):
        dp[i] = dp[i - 1] + nums[i - 1]
        for j in range(i):
            dp[i] = min(dp[i], dp[j] + nums[i - 1] + x)
    return dp[n]

def minSumOfLengths(n, k):
    dp = [[float('inf')] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0
    for i in range(1, n + 1):
        for j in range(k + 1):
            if j >= i:
                dp[i][j] = dp[i - 1][j]
            else:
                dp[i][j] = min(dp[i - 1][j], dp[i - 1][j - i] + 1)
    return dp[n][k]

def minPalindrome(s):
    n = len(s)
    if n == 1:
        return s
    if n == 2:
        return s if s[0] == s[1] else s[0] + s[1]
    if s[0] == s[1]:
        return s[0] + minPalindrome(s[2:])
    else:
        return s[0] + minPalindrome(s[1:])

def minCost(s):
    n = len(s)
    dp = [[float('inf')] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = 0
    for l in range(2, n + 1):
        for i in range(n - l + 1):
            j = i + l - 1
            if s[i] == s[j]:
                dp[i][j] = min(dp[i][j], dp[i + 1][j - 1] + 1)
            else:
                dp[i][j] = min(dp[i][j], min(dp[i + 1][j], dp[i][j - 1]) + 1)
    return dp[0][n - 1]

