def canTraverse(nums):
    def gcd(a, b):
        return a if b == 0 else gcd(b, a % b)

    def can_traverse(i, j):
        return gcd(nums[i], nums[j]) > 1

    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if can_traverse(i, j):
                return True
    return False

