def numSpecialPermutations(nums):
    MOD = 10**9 + 7
    n = len(nums)
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, n + 1):
        dp[i] = (dp[i - 1] * 2) % MOD
        for j in range(i):
            if nums[j] % nums[i] == 0:
                dp[i] = (dp[i] - dp[j] * dp[i - j - 1]) % MOD
