def maxLength(x, y, z):
    # Create a set to store all possible substrings
    substrings = set()
    for i in range(x+1):
        for j in range(y+1):
            for k in range(z+1):
                substrings.add("".join(sorted(list(str(i)) + list(str(j)) + list(str(k)))))

    # Create a set to store all substrings that are not "AAA" or "BBB"
    valid_substrings = set()
    for substring in substrings:
        if "AAA" not in substring and "BBB" not in substring:
            valid_substrings.add(substring)

    # Find the maximum length of the valid substrings
    max_length = max(len(substring) for substring in valid_substrings)
    return max_length

def minLength(words):
