def longestSubarray(nums, threshold):
    n = len(nums)
    l = 0
    r = 0
    max_len = 0
    while r < n:
        while r < n and nums[r] <= threshold:
            r += 1
        if r - l > max_len:
            max_len = r - l
        while l < r and nums[l] % 2 == 0:
            l += 1
        l += 1
    return max_len

def numOfGoodSubarrays(nums):
