def min_letter_changes(s, k):
    n = len(s)
    dp = [[float('inf')] * n for _ in range(k)]
    dp[0][0] = 0
    for i in range(1, n):
        dp[0][i] = dp[0][i - 1] + 1
        for j in range(i):
            if s[j] != s[i]:
                dp[0][i] = min(dp[0][i], dp[0][j] + 1)
    for i in range(1, k):
        for j in range(n - i + 1):
            for k in range(j + 1, n - i + 1):
                if s[j] != s[k]:
                    dp[i][j:k] = min(dp[i][j:k], dp[i - 1][j] + 1)
    return dp[k - 1][n - 1]

