def getPermutation(s):
    vowels = 'aeiouAEIOU'
    consonants = 'bcdfghjklmnpqrstvwxyzBCDFGHJKLMNPQRSTVWXYZ'
    vowels_index = [i for i, char in enumerate(s) if char in vowels]
    consonants_index = [i for i, char in enumerate(s) if char in consonants]
    vowels_sorted = sorted(vowels)
    consonants_sorted = sorted(consonants)
    vowels_sorted_index = [vowels_sorted.index(char) for char in s]
    consonants_sorted_index = [consonants_sorted.index(char) for char in s]
    result = []
    for i in range(len(s)):
        if i in vowels_index:
            result.append(s[i])
        elif i in consonants_index:
            result.append(s[i])
        else:
            if vowels_sorted_index[i] < consonants_sorted_index[i]:
                result.append(s[i])
            else:
                result.append(s[i])
    return ''.join(result)

def minDominantIndex(nums):
    n = len(nums)
    if n == 1:
        return 0
    max_freq = max(nums)
    max_freq_index = nums.index(max_freq)
    max_freq_count = nums.count(max_freq)
    if max_freq_count > n / 2:
        return max_freq_index
    else:
        for i in range(n):
            if nums[i] == max_freq and nums.count(nums[i]) < max_freq_count:
                return i
        return -1

