def countSteppingNumbers(low, high):
    def isStepping(n):
        return all(abs(int(n[i]) - int(n[i+1])) == 1 for i in range(len(n)-1))

    def countStepping(low, high):
        count = 0
        for i in range(int(low), int(high)+1):
            if isStepping(str(i)):
                count += 1
        return count

    return countStepping(low, high) % (10**9 + 7)

def minTime(nums1, nums2, x):
    n = len(nums1)
    dp = [[float('inf')] * (x + 1) for _ in range(n + 1)]
    dp[0][0] = 0
    for i in range(1, n + 1):
        for j in range(x + 1):
            if j >= nums1[i - 1]:
                dp[i][j] = min(dp[i - 1][j], dp[i - 1][j - nums1[i - 1]] + nums2[i - 1])
            else:
                dp[i][j] = dp[i - 1][j]
    return -1 if dp[n][x] == float('inf') else dp[n][x]

def kthDistinct(coordinates, k):
    def xor_sum(x, y):
        return x ^ y

    def count_pairs(x, y, k):
        count = 0
        for i in range(len(coordinates)):
            for j in range(i + 1, len(coordinates)):
                if xor_sum(x, coordinates[i][0]) == xor_sum(y, coordinates[j][0]) and xor_sum(x, coordinates[i][1]) == xor_sum(y, coordinates[j][1]):
                    count += 1
        return count

    return count_pairs(0, 0, k)

def maxSum(nums, m, k):
    n = len(nums)
    if n < k:
        return 0

    # Create a dictionary to store the frequency of each element
    freq = {}
    for i in range(n):
        if nums[i] in freq:
            freq[nums[i]] += 1
        else:
            freq[nums[i]] = 1

    # Create a list to store the sum of all subarrays of size k
    sums = []

    # Traverse through the array
    for i in range(n - k + 1):
        # Calculate the sum of the current subarray
        subarray_sum = sum(nums[i:i+k])

        # If the subarray is almost unique, add it to the list of sums
        if len(set(nums[i:i+k])) == m:
            sums.append(subarray_sum)

    # Find the maximum sum from the list of sums
    max_sum = max(sums)

    return max_sum

def maxGold(n, offers):
    # Create a 2D array to store the maximum gold earned from each house
    max_gold = [[0 for _ in range(n)] for _ in range(n)]

    # Fill the first row and column with 0
    for i in range(n):
        max_gold[i][i] = 0

    # Fill the rest of the matrix
    for i in range(n):
        for j in range(i + 1, n):
            start_i, end_i, gold_i = offers[i]
            start_j, end_j, gold_j = offers[j]

            # If the houses are in the same range, add the maximum of the two offers
            if start_i <= start_j and end_i >= end_j:
                max_gold[i][j] = max(max_gold[i][j], gold_i + max_gold[start_i][end_j])

            # If the houses are in different ranges, add the maximum of the two offers
            elif start_i <= end_j and end_i >= start_j:
                max_gold[i][j] = max(max_gold[i][j], gold_j + max_gold[start_i][end_j])

            # If the houses are in different ranges, add the maximum of the two offers
            elif start_i >= start_j and end_i <= end_j:
