        for i in range(len(s)):
            if s[i] == '0':
                return False
            if i > 0 and s[i] == s[i-1]:
                return False
        return True

    def dfs(s, index, count):
        if index == len(s):
            return count

        for i in range(index, len(s)):
            if is_valid(s[:index] + s[i] + s[index+1:i] + s[i+1:]):
                s = s[:index] + s[i] + s[index+1:i] + s[i+1:]
                count = dfs(s, index+1, count)
                s = s[:index] + s[i] + s[index+1:i] + s[i+1:]
                return count

        return count

    return dfs(s, 0, 0)

