def solve(N, M, A, S):
    # Create a set to store the elements in each set
    sets = {i: set(S[i]) for i in range(N)}

    # Create a set to store the elements in the final set
    final_set = set()

    # Create a set to store the elements that can be removed
    can_remove = set()

    # Iterate over all sets
    for i in range(N):
        # Iterate over all elements in the set
        for j in range(A[i]):
            # If the element is in the final set, remove it
            if final_set.intersection(sets[i]):
                can_remove.add(j)

    # If there are no elements in the final set, it is impossible to obtain a set containing both 1 and M
    if not final_set:
        return -1

    # Iterate over all elements in the final set
    for i in final_set:
        # If the element is in the can_remove set, remove it
        if i in can_remove:
            can_remove.remove(i)

    # If there are still elements in the can_remove set, it is impossible to obtain a set containing both 1 and M
    if can_remove:
        return -1

    # If there are no elements in the can_remove set, it is possible to obtain a set containing both 1 and M
    return len(can_remove)

