def solve(N1, N2, M):
    # Create a graph with N1+N2 vertices
    graph = [[0]*(N1+N2+1) for _ in range(N1+N2+1)]

    # Add edges according to the given input
    for i in range(M):
        u, v = map(int, input().split())
        graph[u][v] = graph[v][u] = 1

    # Find the minimum length path between vertex 1 and vertex (N1+N2)
    def find_min_path(u, v):
        if graph[u][v] == 1:
            return 0
        if graph[u][v] == 0:
            return float('inf')
        return 1 + min(find_min_path(u, k) for k in range(u+1, v))

    # Find the maximum possible d
    d = find_min_path(1, N1+N2+1)
    return d

