def count_holeless_squares(H, W, N):
    # Initialize the count of holeless squares
    count = 0

    # Iterate over all possible values of n
    for n in range(1, W + 1):
        # Iterate over all possible values of i and j
        for i in range(H):
            for j in range(W):
                # Check if the square (i, j) is holed
                if (i + n - 1) >= H or (j + n - 1) >= W:
                    continue
                # Check if the square (i, j) is not holed
                for k in range(n):
                    for l in range(n):
                        # Check if the square (i + k, j + l) is holed
                        if (i + k + n - 1) >= H or (j + l + n - 1) >= W:
                            continue
                        # If the square (i, j) is not holed and the square (i + k, j + l) is not holed,
                        # then the square (i, j) is a holeless square
                        if not (i + k, j + l) in holes:
                            count += 1
                            holes.add((i + k, j + l))

    return count

