def ta_code(grid):
    def is_valid(i, j):
        if i < 0 or j < 0 or i >= len(grid) or j >= len(grid[0]):
            return False
        return grid[i][j] == '#'

    def is_adjacent(i, j):
        if i < 0 or j < 0 or i >= len(grid) or j >= len(grid[0]):
            return False
        return any(grid[i+k][j+l] == '#' for k in range(-1, 2) for l in range(-1, 2))

    def is_tak_code(i, j):
        if not is_valid(i, j) or not is_adjacent(i, j):
            return False
        for k in range(1, 10):
            if not is_valid(i+k, j) or not is_adjacent(i+k, j):
                return False
            if not is_valid(i, j+k) or not is_adjacent(i, j+k):
                return False
            if not is_valid(i-k, j) or not is_adjacent(i-k, j):
                return False
            if not is_valid(i, j-k) or not is_adjacent(i, j-k):
                return False
        return True

    regions = []
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if is_tak_code(i, j):
                regions.append((i, j))
    return sorted(regions)

