def solve(H, W, S):
    # Create a graph where each cell is a vertex and an edge exists between two adjacent cells
    graph = [[0]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if S[i][j] == '#':
                graph[i][j] = 1
            else:
                graph[i][j] = 0

    # Perform DFS to count the number of connected components
    def dfs(i, j, visited):
        if 0 <= i < H and 0 <= j < W and graph[i][j] == 1 and not visited[i][j]:
            visited[i][j] = True
            for di, dj in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                dfs(i + di, j + dj, visited)

    # Initialize the number of connected components
    num_components = 0

    # Perform DFS for each cell
    for i in range(H):
        for j in range(W):
            if graph[i][j] == 1:
                num_components += 1
                dfs(i, j, [False] * W)

    # Calculate the expected value
    expected_value = num_components * 2
    expected_value %= 998244353

    # Print the expected value
    print(expected_value)

