def longestSubarray(nums):
    n = len(nums)
    left = 0
    right = 0
    max_len = 0
    max_start = 0
    max_end = 0
    while right < n:
        if nums[right] > nums[right - 1]:
            right += 1
        else:
            while left <= right and nums[left] <= nums[right - 1]:
                left += 1
            if left <= right:
                max_len = max(max_len, right - left + 1)
                max_start = left
                max_end = right
            right += 1
    return max_len

def smallestStringWithSwaps(s, k):
    n = len(s)
    d = {}
    for i in range(n):
        d[s[i]] = d.get(s[i], []) + [i]

    def find(x):
        if x != d[x][0]:
            d[x][0] = find(d[x][0])
        return d[x][0]

    def union(x, y):
        x = find(x)
        y = find(y)
        if x != y:
            d[x] = [i for i in d[y] if i != x]
            d[y] = [i for i in d[x] if i != y]
            d[x].append(y)
            d[y].append(x)
            d[x].sort()
            d[y].sort()
            d[x][0] = x
            d[y][0] = y

    for i in range(n):
        for j in range(i + 1, n):
            if s[i] != s[j]:
                union(i, j)

    d = {k: v for k, v in d.items() if len(v) > 1}
    if not d:
        return s

    def find_min(x):
        if x != d[x][0]:
            d[x][0] = find_min(d[x][0])
        return d[x][0]

    def union_min(x, y):
        x = find_min(x)
        y = find_min(y)
        if x != y:
            d[x] = [i for i in d[y] if i != x]
            d[y] = [i for i in d[x] if i != y]
            d[x].append(y)
            d[y].append(x)
            d[x].sort()
            d[y].sort()
            d[x][0] = x
            d[y][0] = y

    for i in range(n):
        for j in range(i + 1, n):
            if s[i] != s[j]:
                union_min(i, j)

    d = {k: v for k, v in d.items() if len(v) == 1}
    if not d:
        return s

    return ''.join(d[k] for k in d)

