def convert_to_12_hour(s):
    # Split the string into hours and minutes
    hours, minutes = map(int, s.split(':'))

    # Check if the hours are valid
    if hours < 0 or hours > 11:
        return "00:00"

    # Check if the minutes are valid
    if minutes < 0 or minutes > 59:
        return "00:00"

    # Check if the hours and minutes are valid
    if hours < 10:
        hours = "0" + str(hours)
    else:
        hours = str(hours)

    if minutes < 10:
        minutes = "0" + str(minutes)
    else:
        minutes = str(minutes)

    # Return the formatted time
    return hours + ":" + minutes

def maximumGap(nums):
    if len(nums) < 2:
        return 0

    primes = [True] * (max(nums) + 1)
    primes[0] = primes[1] = False
    for i in range(2, int(max(nums) ** 0.5) + 1):
        if primes[i]:
            for j in range(i * i, max(nums) + 1, i):
                primes[j] = False

    nums = sorted(set(nums))
    max_gap = 0
    for i in range(len(nums) - 1):
        gap = nums[i + 1] - nums[i]
        max_gap = max(max_gap, gap)

