def sumUnmarked(nums, queries):
    unmarked = set()
    for num in nums:
        unmarked.add(num)
    result = []
    for i, k in queries:
        if i in unmarked:
            unmarked.remove(i)
            for j in range(k):
                if i - j in unmarked:
                    unmarked.remove(i - j)
                if len(unmarked) < k:
                    unmarked.add(i - j)
        result.append(sum(unmarked))
    return result

