def sumOfSubsequenceWeights(nums, k):
    MOD = 10**9 + 7
    dp = [0] * (k + 1)
    dp[0] = 1
    for num in nums:
        for j in range(k, num - 1, -1):
            dp[j] = (dp[j] + dp[j - num]) % MOD
    return dp[k]

def shortestSubarray(nums, k):
    n = len(nums)
    dp = [0] * (n + 1)
    for i in range(n):
        dp[i + 1] = dp[i] + nums[i]
    dp.sort()
    res = float('inf')
    for i in range(n + 1):
        j = bisect_right(dp, k - dp[i])
        if j != i:
            res = min(res, i - j + 1)
    return -1 if res == float('inf') else res

def min_levels(possible):
    n = len(possible)
    dp = [0] * (n + 1)
    dp[0] = 0
    for i in range(1, n + 1):
        if possible[i - 1] == 0:
            dp[i] = dp[i - 1]
        else:
            dp[i] = max(dp[i - 1], dp[i - 2] + 1)
    return n - dp[n]

def sumOfSubsequenceWeights(nums, k):
    MOD = 10**9 + 7
    dp = [0] * (k + 1)
    dp[0] = 0
    for num in nums:
        for i in range(k, num - 1, -1):
            dp[i] = (dp[i] + dp[i - num]) % MOD
    return dp[k]

def scoreOfS(s):
    score = 0
    for i in range(len(s)-1):
        score += abs(ord(s[i]) - ord(s[i+1]))
    return score

def subarraysWithKDistinct(nums, k):
    n = len(nums)
    count = [0] * (n + 1)
    for i in range(n):
        count[i + 1] = count[i] + 1 if nums[i] in count else 1
    res = 0
    for i in range(n + 1):
        for j in range(i + 1, n + 1):
            if count[j] - count[i] == k:
                res += 1
    return res

def countSpecialLetters(word):
    count = 0
    for i in range(len(word)):
        if word[i].isupper() and word[i].islower():
            count += 1
    return count

def minArray(n, x):
    nums = [0] * n
    nums[0] = x
    for i in range(1, n):
        nums[i] = nums[i - 1] * 2 + 1
    return nums[n - 1]

def findMedian(nums):
    nums.sort()
    n = len(nums)
    if n % 2 == 0:
        return (nums[n//2 - 1] + nums[n//2]) / 2
    else:
        return nums[n//2]

def isValid(word):
    # Check if the word has at least 3 characters
    if len(word) < 3:
        return False

    # Check if the word contains at least one vowel
    vowels = 'aeiouAEIOU'
    if word.lower() not in vowels:
        return False

    # Check if the word contains at least one consonant
    consonants = 'bcdfghjklmnpqrstvwxyzBCDFGHJKLMNPQRSTVWXYZ'
    if word.lower() not in consonants:
        return False

    # Check if the word contains at least one digit
    if not any(char.isdigit() for char in word):
        return False

    return True

def minCost(nums, cost1, cost2):
    n = len(nums)
    dp = [[0] * (cost2 + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][0] = 0
    for i in range(1, n + 1):
        for j in range(1, cost2 + 1):
            dp[i][j] = dp[i - 1][j]
            if j >= nums[i - 1]:
                dp[i][j] = min(dp[i][j], dp[i - 1][j - nums[i - 1]] + cost1)
    return dp[n][cost2] % (10**9 + 7)

def can_make_square(grid):
    def dfs(i, j, color):
        if i < 0 or i >= len(grid) or j < 0 or j >= len(grid[0]) or grid[i][j] != color:
            return False
        grid[i][j] = '.'
        for di, dj in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            if dfs(i + di, j + dj, color):
                return True
        grid[i][j] = color
        return False

    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 'B':
                if dfs(i, j, 'W'):
                    return True
    return False

def countRightTriangles(grid):
    count = 0
    for i in range(len(grid)):
        for j in range(i+1, len(grid)):
            for k in range(j+1, len(grid)):
                if grid[i][j] == 1 and grid[j][k] == 1 and grid[k][i] == 1:
                    count += 1
    return count

def stableArrays(zero, one, limit):
    MOD = 10**9 + 7
    dp = [0] * (one + 1)
    dp[0] = 1
    for i in range(zero):
        dp[i + 1] = (dp[i] + dp[i + 1]) % MOD
    for i in range(one):
        dp[i + 1] = (dp[i] + dp[i + 1]) % MOD
    for i in range(limit):
        dp[i + 1] = (dp[i] + dp[i + 1]) % MOD
    return dp[one]

def isSpecial(nums):
    for i in range(len(nums) - 1):
        if nums[i] % 2 == nums[i + 1] % 2:
            return False
    return True

def sumOfDigitDifferences(nums):
    def count_digits(n):
        return len(str(n))

    def digit_diff(a, b):
        return sum(1 for i in range(count_digits(a)) if a % 10 != b % 10)

    return sum(digit_diff(a, b) for a, b in zip(nums, nums[1:]))

def countGoodPairs(nums1, nums2, k):
    count = 0
    for i in range(len(nums1)):
        for j in range(len(nums2)):
            if nums1[i] % (nums2[j] * k) == 0:
                count += 1
    return count

def compress(word):
    comp = ""
    for i in range(len(word)):
        if i == 0:
            comp += str(len(word)) + word[0]
        else:
            if word[i] == word[i-1]:
                comp += str(len(word) - i) + word[i]
            else:
                comp += str(len(word) - i) + word[i]
    return comp

def sumOfSubsequenceWiseProducts(nums, queries):
    mod = 10**9 + 7
    n = len(nums)
    dp = [[0]*n for _ in range(n)]
    for i in range(n):
        dp[i][i] = nums[i]
    for l in range(2, n+1):
        for i in range(n-l+1):
            j = i + l - 1
            dp[i][j] = dp[i][j-1]
            for k in range(i, j):
                dp[i][j] = (dp[i][j] + dp[i][k-1]*dp[k+1][j]) % mod
    ans = 0
    for i, j in queries:
        ans = (ans + dp[i-1][j-1]) % mod
    return ans

def minPartitions(s):
    max_val = 0
    for char in s:
        if char.isdigit():
            max_val = max(max_val, int(char))
    return max_val

def big_nums(queries):
    big_nums = [1]
    for i in range(1, 1000000):
        big_nums.append(2**i)
    return big_nums

def solve(queries):
    answer = []
    for i in range(len(queries)):
        from_i, to_i, mod_i = queries[i]
        product = 1
        for j in range(from_i, to_i+1):
            product *= big_nums[j]
        product %= mod_i
        answer.append(product)
    return answer

def xor_twice(nums):
    xor = 0
    for num in nums:
        xor ^= num
    return xor

